	function Maksimum(ar){
		var max = ar[0];
		for(var i=1;i<ar.length;i++){
			if(max < ar[i]){
				max = ar[i];
			}
		}
		return max;
	}
	function Minimum(ar){
		var mini = ar[0];
		for(var i=1;i<ar.length;i++){
			if(mini > ar[i]){
				mini = ar[i];
			}
		}
		return mini;
	}
	function CariFPB(ar){
		//https://www.ketutrare.com/2019/05/contoh-aplikasi-fpb-dan-kpk-menggunakan-bahasa-c.html
		
		var min = 0;
		var max = 0;
		for(var i=0;i<ar.length;i++){
			min = Math.min(min,ar[i]);
			max = Math.max(max,ar[i]);
		}
		
		var iter = 0;
		var fpb = 1;
		var f = [];
		do {
			iter++;
			ff = 1;
			for(var i=0;i<ar.length;i++){
				f[i] = Mods(ar[i],iter)==0;
				ff *= f[i];
			}
			
			if (ff){
				fpb = iter;
			}
			fakhir = iter==max;
		}while (!fakhir);
		
		return fpb;
	}
	function StrPow(nn){
		var arpow = [
					"\u{2070}",
					"\u{00B9}",
					"\u{00B2}",
					"\u{00B3}",
					"\u{2074}",
					"\u{2075}",
					"\u{2076}",
					"\u{2077}",
					"\u{2078}",
					"\u{2079}"
					]
		var arnn = SplitString(nn);
		var str = "";
		for(var i=0;i<arnn.length;i++){
			str+=arpow[arnn[i]];
		}
		return str;
	}
	function arraysAreEqual(arr1, arr2) {
		if (arr1.length !== arr2.length) {
		   return false;
		}
		return arr1.every((val, index) => val === arr2[index]);
	}
	function NoJawabanBenarEqual(Arr, jwb){
		for (var i=0; i<Arr.length; i++){
			if (arraysAreEqual(Arr[i], jwb)){
				return i;
				break;
			}
		}
	}
	function StringDesimal(ff){
		var strff = ""+ff;
		const gg = strff.split(".");
		if(gg.length==2)	return gg[0]+","+gg[1];
		else 				return ff
	}
	function SortAtoZ(ar){
		ar.sort(function(a, b){return a-b});
		return ar
	}
	function SortZtoA(ar){
		ar.sort(function(a, b){return b-a});
		return ar
	}
